  <desc>\u0413\u043E\u043B\u0443\u0431\u043E\u0439 \u043A\u0440\u0443\u0433\u043B\u044B\u0439 \u043C\u0430\u0441\u043A\u043E\u0442 \u0441 \u0434\u0432\u0443\u043C\u044F \u0441\u0432\u0435\u0442\u043B\u044B\u043C\u0438 \u0433\u043B\u0430\u0437\u0430\u043C\u0438 \u0438 \u0442\u0440\u0435\u043C\u044F \u0434\u0443\u0433\u0430\u043C\u0438 \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0441\u0442\u0438. \u041E\u0440\u0430\u043D\u0436\u0435\u0432\u0430\u044F \u0434\u0443\u0433\u0430 \u2014 \u0441\u043E\u0436\u0436\u0451\u043D\u043D\u044B\u0435 \u043A\u0430\u043B\u043E\u0440\u0438\u0438, \u0441\u0438\u043D\u044F\u044F \u2014 \u043F\u0440\u043E\u0439\u0434\u0435\u043D\u043D\u0430\u044F \u0434\u0438\u0441\u0442\u0430\u043D\u0446\u0438\u044F, \u0437\u0435\u043B\u0451\u043D\u0430\u044F \u2014 \u0441\u044A\u0435\u0434\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u043B\u043E\u0440\u0438\u0438. \u0412\u0441\u0435 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B \u2014 \u0440\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u0443\u0435\u043C\u044B\u0435 \u0432\u0435\u043A\u0442\u043E\u0440\u043D\u044B\u0435 \u0444\u043E\u0440\u043C\u044B.</desc>
  <defs>
